public class BuilderDemo {
    public static void main(String[] args) {

        // StringBuilder — preferred for single-threaded code
        StringBuilder sb = new StringBuilder();
        sb.append("Java");
        sb.append(" is");
        sb.append(" fast");
        System.out.println(sb.toString()); // Java is fast

        // Chaining — append() returns 'this' so calls can be chained
        String result = new StringBuilder()
                .append("Hello")
                .append(", ")
                .append("World")
                .append("!")
                .toString();
        System.out.println(result); // Hello, World!

        // Other useful methods
        StringBuilder s = new StringBuilder("Hello World");
        s.insert(5, ",");          // Hello, World
        s.delete(0, 6);            // World
        s.reverse();               // dlroW
        System.out.println(s);     // dlroW
        System.out.println(s.length()); // 5

        // StringBuffer has identical API — just replace the class name
        // StringBuffer sbf = new StringBuffer();  -- thread-safe but slower
    }
}
