public class StringBuilderMethods {
    public static void main(String[] args) {

        StringBuilder sb = new StringBuilder("Hello");

        // append() — add to the end, overloaded for all types
        sb.append(" World");      // Hello World
        sb.append("!");           // Hello World!
        sb.append(42);            // Hello World!42  (no conversion needed)

        // insert(index, value) — add at a specific position
        sb.insert(5, ",");        // Hello, World!42

        // delete(start, end) — end is exclusive
        sb.delete(13, 15);        // Hello, World!  (removed "42")

        // replace(start, end, str) — swap a range with new text
        sb.replace(7, 12, "Java"); // Hello, Java!

        // reverse() — flips all characters
        StringBuilder rev = new StringBuilder("abcde");
        rev.reverse();
        System.out.println(rev);  // edcba

        // charAt() and setCharAt()
        System.out.println(sb.charAt(0));   // H
        sb.setCharAt(0, 'h');               // hello, Java!

        // deleteCharAt() — remove single character
        sb.deleteCharAt(sb.length() - 1);   // hello, Java

        // length() and toString()
        System.out.println(sb.length());    // 11
        String result = sb.toString();      // convert to immutable String
        System.out.println(result);         // hello, Java
    }
}
