import java.util.List;

public class StringVsBuilder {
    public static void main(String[] args) {

        // USE STRING — single known concatenation, compiler handles it
        String name = "Alice";
        String greeting = "Hello, " + name + "!";  // compiler → StringBuilder internally
        System.out.println(greeting); // Hello, Alice!

        // USE STRING — return values, parameters, constants
        String key = "user.name";
        String value = System.getProperty(key);

        // USE STRINGBUILDER — building in a loop
        List<String> words = List.of("Java", " is", " great");
        StringBuilder sb = new StringBuilder();
        for (String w : words) {
            sb.append(w); // same buffer, no new objects
        }
        String sentence = sb.toString(); // one String at the end
        System.out.println(sentence); // Java is great

        // USE STRINGBUILDER — conditional assembly
        StringBuilder query = new StringBuilder("SELECT * FROM users");
        boolean filterByAge = true;
        boolean filterByCity = false;
        if (filterByAge) query.append(" WHERE age > 18");
        if (filterByCity) query.append(" AND city = 'Delhi'");
        System.out.println(query.toString()); // SELECT * FROM users WHERE age > 18
    }
}
